'use strict';
// ПРОМЕТЕЙ · Пульт продавца — интерфейс
const $=s=>document.querySelector(s),app=$('#app');
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(Number(n)||0)+' ₽';
const dt=v=>v?new Date(v).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
const d=v=>v?String(v).slice(0,10).split('-').reverse().join('.'):'—';
const ago=v=>{if(!v)return 'никогда';const m=Math.round((Date.now()-Date.parse(v))/60000);if(m<2)return 'только что';if(m<60)return m+' мин назад';const h=Math.round(m/60);if(h<48)return h+' ч назад';return Math.round(h/24)+' дн назад'};
const bytes=n=>n>1e9?(n/1e9).toFixed(1)+' ГБ':n>1e6?(n/1e6).toFixed(1)+' МБ':Math.round((n||0)/1e3)+' КБ';
const STATUS={active:'Оплачено',trial:'Пробный',grace:'Просрочено (льгота)',expired:'Не оплачено',blocked:'Заблокировано'};
const badge=s=>`<span class="badge s-${esc(s||'none')}">${esc(STATUS[s]||s||'—')}</span>`;
const SVC={on:'работает',off:'не подключено',warn:'внимание',error:'ошибка'};
function toast(t,bad){const e=document.createElement('div');e.className='toast'+(bad?' bad':'');e.textContent=t;$('#toasts').append(e);setTimeout(()=>e.remove(),3000)}
async function api(p,opt={}){const r=await fetch(p,{credentials:'same-origin',...opt,headers:{'content-type':'application/json','x-prometey':'1',...(opt.headers||{})}});const b=await r.json().catch(()=>({}));if(r.status===401&&p!=='/api/login'){login();throw new Error('Требуется вход')}if(!r.ok)throw new Error(b.error||'Ошибка');return b}
const post=(p,b,method='POST')=>api(p,{method,body:JSON.stringify(b||{})});

function modal(title,html,onSave,saveText='Сохранить'){
 $('#modal').innerHTML=`<div class="backdrop"><form class="modal"><h3>${esc(title)}</h3>${html}<div class="err"></div><div class="actions"><button type="button" class="btn" data-close>Отмена</button>${onSave?`<button class="btn btn-primary">${esc(saveText)}</button>`:''}</div></form></div>`;
 const f=$('#modal form'),close=()=>{$('#modal').innerHTML=''};f.querySelector('[data-close]').onclick=close;f.onkeydown=e=>{if(e.key==='Escape')close()};
 f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('.btn-primary');b.disabled=true;try{await onSave(new FormData(f));close();route()}catch(x){f.querySelector('.err').textContent=x.message;b.disabled=false}};
 f.querySelector('input,select,textarea')?.focus();
}
const fld=(name,label,value='',type='text',extra='')=>`<label class="${type==='textarea'?'full':''}">${esc(label)}${type==='textarea'?`<textarea class="field" name="${name}" rows="3" ${extra}>${esc(value)}</textarea>`:`<input class="field" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`}</label>`;

// ---------- вход ----------
function login(){
 app.innerHTML=`<div class="login"><form><div class="brand"><div class="logo">P</div>ПРОМЕТЕЙ · Пульт продавца</div><p class="muted">Все компании, установки CRM, подписки и оплаты.</p>${fld('email','E-mail','','email','required autocomplete="username"')}${fld('password','Пароль','','password','required autocomplete="current-password"')}<div class="err"></div><button class="btn btn-primary">Войти</button></form></div>`;
 const f=app.querySelector('form');f.onsubmit=async e=>{e.preventDefault();try{await post('/api/login',{email:f.email.value,password:f.password.value});location.hash='#/';shell()}catch(x){f.querySelector('.err').textContent=x.message}};
}
// ---------- каркас ----------
let me=null;
const PAGES=[['','Сводка'],['companies','Компании'],['installs','Установки CRM'],['users','Пользователи'],['payments','Оплаты'],['events','Журнал'],['settings','Настройки']];
async function shell(){
 try{me=await api('/api/me')}catch{return}
 app.innerHTML=`<div class="shell"><aside class="side"><div class="brand"><div class="logo">P</div><div>ПРОМЕТЕЙ<small>Пульт продавца ${esc(me.version)}</small></div></div><nav class="nav">${PAGES.map(([k,t])=>`<button data-go="${k}">${t}<span class="count hidden" data-count="${k}"></span></button>`).join('')}</nav><div class="foot">${esc(me.email)}<br><button id="pw">Сменить пароль</button> · <button id="out">Выйти</button></div></aside><main id="page"></main></div>`;
 app.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{location.hash='#/'+b.dataset.go});
 $('#out').onclick=async()=>{await post('/api/logout');login()};
 $('#pw').onclick=()=>modal('Смена пароля пульта',`<div class="form">${fld('current','Текущий пароль','','password','required')}${fld('next','Новый пароль (от 12 символов)','','password','required minlength="12"')}</div>`,fd=>post('/api/password',{current:fd.get('current'),next:fd.get('next')}).then(()=>toast('Пароль изменён')));
 route();
}
window.onhashchange=()=>{if(me)route()};
async function route(){
 const [page,id]=location.hash.replace(/^#\/?/,'').split('/');const p=$('#page');if(!p)return;
 app.querySelectorAll('[data-go]').forEach(b=>b.classList.toggle('active',b.dataset.go===(page||'')));
 try{
  if(page==='companies'&&id)return await companyPage(p,id);
  if(page==='installs'&&id)return await installPage(p,id);
  await ({'':overviewPage,companies:companiesPage,installs:installsPage,users:usersPage,payments:paymentsPage,events:eventsPage,settings:settingsPage}[page||'']||overviewPage)(p);
 }catch(e){p.innerHTML=`<div class="card">${esc(e.message)}</div>`}
}
const open=(kind,id)=>{location.hash=`#/${kind}/${id}`};

// ---------- сводка ----------
async function overviewPage(p){
 const o=await api('/api/overview');
 const c=$('[data-count=""]');if(c){c.textContent=o.attention.length;c.classList.toggle('hidden',!o.attention.length)}
 p.innerHTML=`<div class="head"><div><h1>Сводка</h1><p class="muted">Подписки, оплаты и состояние всех установленных CRM.</p></div><button class="btn btn-primary" id="new-co">+ Компания</button></div>
 <div class="grid"><div class="kpi dark"><span>Доход в месяц (подписки)</span><b>${money(o.money.mrr)}</b><small>по оплаченным и льготным</small></div><div class="kpi"><span>Поступило в этом месяце</span><b>${money(o.money.thisMonth)}</b><small>прошлый: ${money(o.money.prevMonth)}</small></div><div class="kpi"><span>Компаний</span><b>${o.companies.total}</b><small>оплачено ${o.companies.active} · льгота ${o.companies.grace} · не оплачено ${o.companies.expired} · блок ${o.companies.blocked}</small></div><div class="kpi"><span>Установок CRM</span><b>${o.installs.total}</b><small>на связи ${o.installs.online} · новых ${o.installs.unbound} · молчат ${o.installs.silent}</small></div><div class="kpi"><span>Пользователей во всех CRM</span><b>${o.installs.users}</b><small>всего получено ${money(o.money.total)}</small></div></div>
 <div class="cols"><div><h2>Требует внимания</h2><div class="att">${o.attention.map(a=>`<div class="${esc(a.kind)}" data-ref="${esc(a.ref)}" data-install="${a.install?1:''}">${esc(a.text)}</div>`).join('')||'<div class="card muted ok-left">Всё в порядке: просрочек и проблем нет.</div>'}</div></div>
 <div><h2>Последние события</h2><div class="panel">${o.events.map(e=>`<div class="ev"><span class="small muted">${dt(e.at)}</span><br>${esc(e.text)}</div>`).join('')||'<div class="empty">Событий пока нет</div>'}</div></div></div>`;
 p.querySelectorAll('[data-ref]').forEach(x=>x.onclick=()=>open(x.dataset.install?'installs':'companies',x.dataset.ref));
 $('#new-co').onclick=()=>companyForm();
}
// ---------- компании ----------
function companyForm(c={},afterSave){
 modal(c.id?'Компания':'Новая компания',`<div class="form">${fld('name','Название *',c.name,'text','required')}${fld('inn','ИНН',c.inn)}${fld('contact','Контактное лицо',c.contact)}${fld('phone','Телефон',c.phone)}${fld('email','E-mail',c.email,'email')}${fld('plan','Тариф',c.plan||'Стандарт')}${fld('price','Цена, ₽ в месяц',c.price||'','number','min="0" step="0.01"')}${fld('maxUsers','Пользователей (0 — без ограничения)',c.maxUsers||0,'number','min="0"')}${fld('paidUntil','Оплачено до',c.paidUntil||'','date')}${fld('message','Сообщение в CRM клиента',c.message,'textarea','maxlength="500" placeholder="Например: с 1 декабря новый тариф"')}${fld('note','Заметка (видите только вы)',c.note,'textarea')}</div><p class="small muted">Если ИНН совпадёт с организацией в установленной CRM, установка привяжется к компании сама.</p>`,async fd=>{const b=Object.fromEntries(fd);const r=await post(c.id?'/api/companies/'+c.id:'/api/companies',b,c.id?'PATCH':'POST');toast('Сохранено');if(!c.id)afterSave?afterSave(r):open('companies',r.id)});
}
async function companiesPage(p){
 const list=await api('/api/companies');let q='',st='';
 p.innerHTML=`<div class="head"><div><h1>Компании</h1><p class="muted">Клиенты, которые пользуются ПРОМЕТЕЙ, их тарифы и оплаты.</p></div><button class="btn btn-primary" id="new-co">+ Компания</button></div><div class="filters"><input class="field" id="q" placeholder="Название или ИНН"><select class="field" id="st"><option value="">Все</option>${Object.entries(STATUS).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div class="panel table-wrap"><table><thead><tr><th>Компания</th><th>Статус</th><th>Оплачено до</th><th>Тариф</th><th>Установки</th><th>Пользователи</th><th>На связи</th><th>Получено всего</th></tr></thead><tbody id="rows"></tbody></table></div>`;
 const draw=()=>{const rows=list.filter(c=>(!q||(c.name+' '+(c.inn||'')).toLowerCase().includes(q))&&(!st||c.status===st));$('#rows').innerHTML=rows.map(c=>`<tr class="click" data-id="${esc(c.id)}"><td><b>${esc(c.name)}</b><div class="small muted">${c.inn?'ИНН '+esc(c.inn):''} ${esc(c.contact||'')}</div></td><td>${badge(c.status)}</td><td>${d(c.paidUntil)}</td><td>${esc(c.plan||'')}<div class="small muted">${money(c.price)}/мес</div></td><td>${c.installCount}</td><td>${c.users}${c.maxUsers?' / '+c.maxUsers:''}</td><td>${ago(c.lastSeen)}</td><td>${money(c.paidTotal)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">Компаний нет</td></tr>';$('#rows').querySelectorAll('[data-id]').forEach(r=>r.onclick=()=>open('companies',r.dataset.id))};
 $('#q').oninput=e=>{q=e.target.value.trim().toLowerCase();draw()};$('#st').onchange=e=>{st=e.target.value;draw()};$('#new-co').onclick=()=>companyForm();draw();
}
async function companyPage(p,id){
 const {company:c,installs,payments}=await api('/api/companies/'+id);
 p.innerHTML=`<div class="head"><div><a href="#/companies" class="small muted">← Компании</a><h1>${esc(c.name)} ${badge(c.status)}</h1><p class="muted">${c.inn?'ИНН '+esc(c.inn)+' · ':''}${esc(c.contact||'')} ${esc(c.phone||'')} ${esc(c.email||'')}</p></div><div class="actions"><button class="btn btn-primary" id="pay">+ Оплата</button><button class="btn" id="edit">Изменить</button><button class="btn ${c.blocked?'':'btn-danger'}" id="block">${c.blocked?'Разблокировать':'Заблокировать'}</button></div></div>
 <div class="grid"><div class="kpi dark"><span>Оплачено до</span><b>${d(c.paidUntil)}</b><small>${esc(STATUS[c.status]||'')}</small></div><div class="kpi"><span>Тариф</span><b>${money(c.price)}</b><small>${esc(c.plan||'')} в месяц</small></div><div class="kpi"><span>Пользователей</span><b>${c.users}${c.maxUsers?' / '+c.maxUsers:''}</b><small>${c.maxUsers?'по тарифу':'без ограничения'}</small></div><div class="kpi"><span>Получено всего</span><b>${money(c.paidTotal)}</b><small>последняя оплата ${d(c.lastPaymentAt)}</small></div></div>
 ${c.message?`<p class="card">Сообщение в CRM: <b>${esc(c.message)}</b></p>`:''}${c.note?`<p class="card muted">${esc(c.note)}</p>`:''}
 <h2>Установки CRM</h2><div class="panel table-wrap"><table><thead><tr><th>Установка</th><th>Версия</th><th>На связи</th><th>Пользователи</th><th>Сервисы</th></tr></thead><tbody>${installs.map(i=>`<tr class="click" data-inst="${esc(i.id)}"><td><b>${esc(i.reported?.companyName||i.id.slice(0,8))}</b><div class="small muted">${esc(i.host?.hostname||'')} ${esc(i.host?.os||'')}</div></td><td>${esc(i.version)}</td><td><span class="dot ${i.online?'on':'error'}"></span>${ago(i.lastSeen)}</td><td>${i.stats?.users||0}</td><td>${svcIcons(i.services)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Пока нет. Установка привяжется сама по ИНН или выберите её в «Установки CRM».</td></tr>'}</tbody></table></div>
 <h2>Оплаты</h2><div class="panel table-wrap"><table><thead><tr><th>Дата</th><th>Сумма</th><th>Период</th><th>Оплачено до</th><th>Комментарий</th><th></th></tr></thead><tbody>${payments.map(x=>`<tr class="${x.cancelled?'cancelled':''}"><td>${d(x.date)}</td><td><b>${money(x.amount)}</b></td><td>${x.months?x.months+' мес.':'—'}</td><td>${d(x.paidUntilAfter)}</td><td>${esc(x.method)} ${esc(x.comment)}</td><td>${x.cancelled?'отменён':`<button class="btn btn-sm btn-danger" data-cancel="${esc(x.id)}">Отменить</button>`}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Оплат пока нет</td></tr>'}</tbody></table></div>
 <p><button class="btn btn-sm btn-danger" id="archive">Убрать компанию в архив</button></p>`;
 p.querySelectorAll('[data-inst]').forEach(r=>r.onclick=()=>open('installs',r.dataset.inst));
 $('#edit').onclick=()=>companyForm(c);
 $('#block').onclick=()=>modal(c.blocked?'Разблокировать?':'Заблокировать компанию?',c.blocked?'<p>CRM клиента снова заработает полностью после ближайшей проверки (до нескольких часов) или сразу после кнопки «Проверить» в CRM.</p>':'<p>CRM клиента перейдёт в режим «только просмотр»: данные видны и выгружаются, изменять нельзя. Сработает при ближайшей проверке.</p>',()=>post('/api/companies/'+id,{blocked:!c.blocked},'PATCH'),c.blocked?'Разблокировать':'Заблокировать');
 $('#pay').onclick=()=>modal('Оплата · '+c.name,`<div class="form">${fld('amount','Сумма, ₽ *',c.price||'','number','required min="0.01" step="0.01"')}${fld('months','Продлить на, мес.',1,'number','min="0" max="36"')}${fld('date','Дата платежа',new Date().toISOString().slice(0,10),'date')}<label>Способ<select class="field" name="method"><option>Счёт</option><option>Карта</option><option>Наличные</option><option>Другое</option></select></label>${fld('comment','Комментарий (номер счёта и т. п.)','','text')}</div><p class="small muted">Оплачено до ${d(c.paidUntil)}. Продление считается от этой даты, а если она прошла — от сегодня.</p>`,fd=>post('/api/companies/'+id+'/payments',Object.fromEntries(fd)).then(r=>toast('Оплата записана, оплачено до '+d(r.company.paidUntil))),'Записать оплату');
 p.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>modal('Отменить платёж?','<p>Если платёж продлевал подписку, дата «Оплачено до» вернётся назад.</p>',()=>api('/api/payments/'+b.dataset.cancel,{method:'DELETE'}),'Отменить платёж'));
 $('#archive').onclick=()=>modal('Убрать в архив?','<p>Компания пропадёт из списков. Установки останутся, их можно привязать к другой компании.</p>',()=>api('/api/companies/'+id,{method:'DELETE'}).then(()=>{location.hash='#/companies'}),'В архив');
}
// ---------- установки ----------
const svcIcons=list=>`<span class="svc-icons">${(list||[]).map(s=>`<i class="${esc(s.status)}" title="${esc(s.name+': '+(SVC[s.status]||s.status)+(s.detail?' — '+s.detail:''))}"></i>`).join('')}</span>`;
async function installsPage(p){
 const list=await api('/api/installs');let f='';
 p.innerHTML=`<div class="head"><div><h1>Установки CRM</h1><p class="muted">Каждая установленная CRM сама выходит на связь каждые несколько часов: версия, пользователи, подключённые сервисы.</p></div></div><div class="filters"><select class="field" id="f"><option value="">Все</option><option value="new">Новые (не привязаны)</option><option value="silent">Не на связи</option><option value="error">С ошибками сервисов</option></select></div><div class="panel table-wrap"><table><thead><tr><th>CRM</th><th>Компания</th><th>Статус</th><th>Версия</th><th>На связи</th><th>Пользователи</th><th>Сервисы</th></tr></thead><tbody id="rows"></tbody></table></div>`;
 const draw=()=>{const rows=list.filter(i=>!f||(f==='new'&&!i.companyId)||(f==='silent'&&!i.online)||(f==='error'&&(i.services||[]).some(s=>s.status==='error')));$('#rows').innerHTML=rows.map(i=>`<tr class="click" data-id="${esc(i.id)}"><td><b>${esc(i.reported?.companyName||'Без названия')}</b><div class="small muted">${i.reported?.inn?'ИНН '+esc(i.reported.inn)+' · ':''}${esc(i.host?.hostname||'')} · ${esc(i.lastIp||'')}</div></td><td>${i.companyName?esc(i.companyName):'<span class="badge s-trial">Новая</span>'}</td><td>${badge(i.status)}</td><td>${esc(i.version)}</td><td><span class="dot ${i.online?'on':'error'}"></span>${ago(i.lastSeen)}</td><td>${i.stats?.users||0}<div class="small muted">активны ${i.stats?.activeUsers||0}</div></td><td>${svcIcons(i.services)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Установок нет. Они появятся, как только CRM, собранная с адресом этого пульта, будет установлена и запущена.</td></tr>';$('#rows').querySelectorAll('[data-id]').forEach(r=>r.onclick=()=>open('installs',r.dataset.id))};
 $('#f').onchange=e=>{f=e.target.value;draw()};draw();
}
async function installPage(p,id){
 const [i,companies]=await Promise.all([api('/api/installs/'+id),api('/api/companies')]);const s=i.stats||{};
 p.innerHTML=`<div class="head"><div><a href="#/installs" class="small muted">← Установки</a><h1>${esc(i.reported?.companyName||'Установка')} ${badge(i.status)}</h1><p class="muted">ID ${esc(i.id)} · версия ${esc(i.version)} · ${esc(i.host?.os||'')} · Node.js ${esc(i.host?.node||'')}</p></div><div class="actions"><button class="btn ${i.blocked?'':'btn-danger'}" id="block">${i.blocked?'Разблокировать':'Заблокировать установку'}</button><button class="btn" id="msg">Сообщение в CRM</button></div></div>
 <div class="cols"><div class="card"><h2 class="mt0">Компания и подписка</h2><label>Привязана к компании<select class="field" id="bind"><option value="">— не привязана (пробный период) —</option>${companies.map(c=>`<option value="${esc(c.id)}" ${c.id===i.companyId?'selected':''}>${esc(c.name)}${c.inn?' · '+esc(c.inn):''}</option>`).join('')}</select></label><div class="actions mt8"><button class="btn btn-sm" id="new-co">+ Создать компанию из этой установки</button>${i.companyId?`<a class="btn btn-sm" href="#/companies/${esc(i.companyId)}">Открыть компанию</a>`:''}</div>
 <dl class="mt14"><dt>Статус</dt><dd>${badge(i.status)} ${i.until?'до '+d(i.until):''}</dd>${!i.companyId?`<dt>Пробный период</dt><dd>до ${d(i.until)} <button class="btn btn-sm" id="trial">Изменить</button></dd>`:''}<dt>Сообщение</dt><dd>${esc(i.license?.message||'—')}</dd><dt>Первый запуск</dt><dd>${dt(i.firstSeen)}</dd><dt>Последняя связь</dt><dd><span class="dot ${i.online?'on':'error'}"></span>${dt(i.lastSeen)} (${ago(i.lastSeen)})</dd><dt>IP-адрес</dt><dd>${esc(i.lastIp)}</dd><dt>Компьютер</dt><dd>${esc(i.host?.hostname||'—')}, ${i.host?.lan?'доступ из сети включён':'только этот компьютер'}</dd></dl></div>
 <div class="card"><h2 class="mt0">Использование</h2><dl><dt>Пользователей</dt><dd><b>${s.users||0}</b>, активных за 30 дней — ${s.activeUsers||0}</dd><dt>Последний вход</dt><dd>${dt(s.lastLoginAt)}</dd><dt>Компаний-клиентов</dt><dd>${s.clients||0}</dd><dt>Сделок</dt><dd>${s.orders||0}</dd><dt>Документов</dt><dd>${s.documents||0}</dd><dt>Своих шаблонов</dt><dd>${s.templates||0}</dd><dt>База данных</dt><dd>${bytes(s.dbBytes)}</dd><dt>Резервная копия</dt><dd>${dt(i.lastBackupAt)}</dd><dt>Ошибок за сутки</dt><dd>${i.errors24h||0}</dd></dl></div></div>
 <h2>Подключённые сервисы</h2><div class="services">${(i.services||[]).map(x=>`<div class="svc"><b><span class="dot ${esc(x.status)}"></span>${esc(x.name)}</b><small>${esc(SVC[x.status]||x.status)}${x.detail?' · '+esc(x.detail):''}</small></div>`).join('')||'<div class="muted">Нет данных</div>'}</div>
 <h2>Пользователи по дням</h2><div class="card">${chart(i.history||[])}</div>
 <h2>Заметка</h2><div class="card"><textarea class="field" id="note" rows="3" placeholder="Видите только вы">${esc(i.note||'')}</textarea><div class="actions mt8"><button class="btn btn-sm" id="save-note">Сохранить заметку</button><button class="btn btn-sm btn-danger" id="del">Удалить из списка</button></div></div>`;
 const patch=b=>post('/api/installs/'+id,b,'PATCH');
 $('#bind').onchange=async e=>{try{await patch({companyId:e.target.value});toast('Привязка сохранена');route()}catch(x){toast(x.message,true)}};
 $('#new-co').onclick=()=>companyForm({name:i.reported?.companyName||'',inn:i.reported?.inn||''},async co=>{await patch({companyId:co.id});toast('Компания создана и привязана');route()});
 $('#trial')?.addEventListener('click',()=>modal('Пробный период',fld('trialUntil','Пробный период до',(i.until||'').slice(0,10),'date','required'),fd=>patch({trialUntil:fd.get('trialUntil')})));
 $('#block').onclick=()=>modal(i.blocked?'Разблокировать?':'Заблокировать установку?',i.blocked?'<p>CRM снова заработает полностью при ближайшей проверке.</p>':'<p>CRM перейдёт в режим «только просмотр» при ближайшей проверке.</p>',()=>patch({blocked:!i.blocked}),i.blocked?'Разблокировать':'Заблокировать');
 $('#msg').onclick=()=>modal('Сообщение в CRM',`<p class="muted small">Его увидят все пользователи этой CRM в верхней строке. Пустое — убрать.</p>${fld('message','Текст',i.message||'','textarea','maxlength="500"')}`,fd=>patch({message:fd.get('message')}));
 $('#save-note').onclick=async()=>{await patch({note:$('#note').value});toast('Заметка сохранена')};
 $('#del').onclick=()=>modal('Удалить установку из списка?','<p>Если эта CRM снова выйдет на связь, она появится как новая.</p>',()=>api('/api/installs/'+id,{method:'DELETE'}).then(()=>{location.hash='#/installs'}),'Удалить');
}
function chart(h){if(!h.length)return '<span class="muted">Данных пока нет</span>';const w=Math.max(300,h.length*12),max=Math.max(1,...h.map(x=>x.users));const bars=h.map((x,i)=>{const y=Math.round(x.users/max*80);return `<rect x="${i*12}" y="${90-y}" width="9" height="${y}" rx="2" fill="#ea5b0c"><title>${esc(d(x.day))}: ${x.users} польз., активных ${x.activeUsers}, версия ${esc(x.version)}</title></rect>`}).join('');return `<svg viewBox="0 0 ${w} 100" class="chart" role="img" aria-label="Пользователи по дням">${bars}</svg><div class="small muted">${d(h[0].day)} — ${d(h.at(-1).day)}, максимум ${max}</div>`}
// ---------- оплаты ----------
async function paymentsPage(p){
 const month=sessionStorage.getItem('pv-month')||new Date().toISOString().slice(0,7);const list=await api('/api/payments?month='+encodeURIComponent(month));const live=list.filter(x=>!x.cancelled);
 p.innerHTML=`<div class="head"><div><h1>Оплаты</h1><p class="muted">Все поступления по подпискам.</p></div><div class="actions"><input class="field auto" type="month" id="m" value="${esc(month)}"><a class="btn" href="/api/payments?format=csv&month=${encodeURIComponent(month)}" download>Выгрузить в Excel (CSV)</a></div></div>
 <div class="grid"><div class="kpi dark"><span>Поступило за месяц</span><b>${money(live.reduce((s,x)=>s+x.amount,0))}</b><small>${live.length} платежей</small></div></div><br>
 <div class="panel table-wrap"><table><thead><tr><th>Дата</th><th>Компания</th><th>Сумма</th><th>Период</th><th>Оплачено до</th><th>Способ / комментарий</th></tr></thead><tbody>${list.map(x=>`<tr class="click ${x.cancelled?'cancelled':''}" data-co="${esc(x.companyId)}"><td>${d(x.date)}</td><td>${esc(x.companyName)}</td><td><b>${money(x.amount)}</b></td><td>${x.months?x.months+' мес.':'—'}</td><td>${d(x.paidUntilAfter)}</td><td>${esc(x.method)} ${esc(x.comment)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">За этот месяц оплат нет</td></tr>'}</tbody></table></div>`;
 $('#m').onchange=e=>{sessionStorage.setItem('pv-month',e.target.value);route()};p.querySelectorAll('[data-co]').forEach(r=>r.onclick=()=>open('companies',r.dataset.co));
}
async function usersPage(p){
 const r=await api('/api/users');let q='',only='active';
 p.innerHTML=`<div class="head"><div><h1>Пользователи</h1><p class="muted">Актуальные e-mail сотрудников во всех установленных CRM — только тех, кто принял политику обработки персональных данных. Обновляется при каждой связи CRM с пультом.</p></div><div class="actions"><button class="btn" id="copy">Скопировать адреса</button><a class="btn btn-dark" href="/api/users?format=csv" download>Выгрузить в Excel (CSV)</a></div></div>
 <div class="grid"><div class="kpi dark"><span>Адресов с согласием</span><b>${r.users.filter(u=>!u.disabled).length}</b><small>всего записей ${r.users.length}</small></div><div class="kpi"><span>Ещё не приняли политику</span><b>${r.withoutConsent}</b><small>их адреса не передаются</small></div><div class="kpi"><span>Компаний</span><b>${new Set(r.users.map(u=>u.installId)).size}</b></div></div><br>
 <div class="filters"><input class="field" id="q" placeholder="E-mail, имя или компания"><select class="field auto" id="only"><option value="active">Активные</option><option value="">Все</option><option value="disabled">Отключённые</option></select></div>
 <div class="panel table-wrap"><table><thead><tr><th>E-mail</th><th>Имя</th><th>Компания</th><th>Роль</th><th>Согласие</th><th>Последний вход</th></tr></thead><tbody id="rows"></tbody></table></div>`;
 const rows=()=>r.users.filter(u=>(!q||(u.email+' '+u.name+' '+u.companyName).toLowerCase().includes(q))&&(!only||(only==='active'?!u.disabled:u.disabled)));
 const draw=()=>{$('#rows').innerHTML=rows().map(u=>`<tr class="${u.disabled?'cancelled':''}"><td><a href="mailto:${esc(u.email)}">${esc(u.email)}</a></td><td>${esc(u.name)}</td><td>${u.companyId?`<a href="#/companies/${esc(u.companyId)}">${esc(u.companyName)}</a>`:esc(u.companyName)}</td><td>${esc(u.role)}</td><td class="small">${dt(u.consentAt)}</td><td class="small">${dt(u.lastLoginAt)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Пока нет. Адреса появятся после того, как сотрудники примут политику в своей CRM.</td></tr>'};
 $('#q').oninput=e=>{q=e.target.value.trim().toLowerCase();draw()};$('#only').onchange=e=>{only=e.target.value;draw()};
 $('#copy').onclick=()=>{const list=[...new Set(rows().filter(u=>!u.disabled).map(u=>u.email))].join(', ');navigator.clipboard?.writeText(list).then(()=>toast('Скопировано адресов: '+list.split(', ').filter(Boolean).length),()=>toast(list))};draw();
}
async function eventsPage(p){const list=await api('/api/events');p.innerHTML=`<div class="head"><div><h1>Журнал</h1><p class="muted">Новые установки, оплаты, блокировки, входы в пульт.</p></div></div><div class="panel table-wrap"><table><thead><tr><th>Когда</th><th>Событие</th></tr></thead><tbody>${list.map(e=>`<tr><td class="small">${dt(e.at)}</td><td>${esc(e.text)}</td></tr>`).join('')||'<tr><td colspan="2" class="empty">Пусто</td></tr>'}</tbody></table></div>`}
async function settingsPage(p){
 const s=await api('/api/settings');const r=s.rules;
 p.innerHTML=`<div class="head"><div><h1>Настройки</h1><p class="muted">Правила подписки и подключение CRM к пульту.</p></div></div>
 <div class="cols"><form class="card" id="rules"><h2 class="mt0">Правила подписки</h2><div class="form">${fld('trialDays','Пробный период, дней',r.trialDays,'number','min="0" max="365"')}${fld('graceDays','Льготный период после неоплаты, дней',r.graceDays,'number','min="0" max="90"')}${fld('checkHours','CRM выходит на связь каждые, ч',r.checkHours,'number','min="1" max="48"')}${fld('offlineWarnDays','Предупреждать, если молчит, дней',r.offlineWarnDays,'number','min="1" max="60"')}</div><p class="small muted">Когда подписка не оплачена и льготный период прошёл, CRM клиента работает «только для просмотра»: данные видны и выгружаются, но изменять ничего нельзя. После оплаты всё включается само.</p><button class="btn btn-primary">Сохранить</button></form>
 <div class="card"><h2 class="mt0">Подключение CRM к пульту</h2><p>Эти два значения вшиваются в установщик CRM при сборке — после этого каждая установленная CRM сама появится в «Установках».</p><label>Адрес пульта</label><div class="code">${esc(s.serverUrl)}</div><label class="mt8">Открытый ключ подписи</label><div class="code">${esc(s.publicKey)}</div><label class="mt8">Сборка установщика</label><div class="code">LICENSE_SERVER=${esc(s.serverUrl)} \\\nLICENSE_KEY=${esc(s.publicKey)} \\\nNODE_EXE=/путь/node.exe CRM=../crm ./build.sh</div><p class="small muted">Закрытый ключ хранится только на этом сервере (data/license-signing-key.pem) — подделать ответ пульта нельзя. Сохраните его в резервной копии.</p></div></div>`;
 const pol=await api('/api/policy');p.insertAdjacentHTML('beforeend',`<form class="card mt14" id="pol"><h2 class="mt0">Политика обработки персональных данных</h2><p class="muted small">Каждый сотрудник в CRM принимает политику при первом входе. Укажите свои реквизиты как разработчика — они подставятся в стандартный текст во всех CRM. Можно вставить и свой текст (абзацы — через пустую строку); при смене редакции все сотрудники примут её заново.</p><div class="form">${fld('name','Разработчик (ИП или организация)',pol.name)}${fld('inn','ИНН',pol.inn)}${fld('email','E-mail для обращений',pol.email,'email')}${fld('version','Редакция своего текста (например, 2026-11-15)',pol.version)}${fld('text','Свой текст политики (необязательно)',pol.text,'textarea','rows="8"')}</div><button class="btn btn-primary">Сохранить</button></form>`);
 $('#pol').onsubmit=async e=>{e.preventDefault();try{await post('/api/policy',Object.fromEntries(new FormData(e.target)),'PATCH');toast('Сохранено — уйдёт в CRM при следующей связи')}catch(x){toast(x.message,true)}};
 $('#rules').onsubmit=async e=>{e.preventDefault();try{await post('/api/settings',Object.fromEntries(new FormData(e.target)),'PATCH');toast('Сохранено')}catch(x){toast(x.message,true)}};
}
api('/api/me').then(()=>shell()).catch(()=>login());
